object a = 5;
int b = (int)a;
b = 9;
// After unboxing to b and reassigning, `a` must still be 5 (copy semantics).
Cj.Eq((int)a, 5, "unboxed copy independent");
// Boxed value types never compare by identity against boxed copies via Equals chain:
object c = 5;
Cj.True(a.Equals(c), "Equals compares boxed values");
Cj.False(ReferenceEquals(a, c), "distinct boxes");
